INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','advanced-passives','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"advanced-passives","title":"Advanced passives and causative have/get","level":"C1","order":59,"summary":"Report beliefs impersonally, combine passive with perfect forms, and describe services someone arranges.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Impersonal reporting","Earlier events after a reporting passive","Arrange for someone else to do something","Get-passives and affected experiences"],"rules":[{"title":"Impersonal reporting","explanation":"A reporting passive can avoid naming who holds a view: **It is believed that ...**. Another pattern makes the reported subject the main subject: **She is believed to ...**. These constructions report a claim; they do not establish that it is true.","pattern":"It is believed that she lives here. / She is believed **to live** here.","commonMistakes":["Do not confuse the time of the belief with the time of the event being reported."],"examples":["Report a habitual activity impersonally: “She is believed **to prepare** the visitor guide every week.”","Report a habitual activity impersonally: “She is believed **to restore** the old portrait every week.”"],"skill":"form"},{"title":"Earlier events after a reporting passive","explanation":"Use a **perfect infinitive** when the reported event is earlier than the reporting reference: is believed to have left. A continuous infinitive can show an ongoing activity: is thought to be working. A passive infinitive adds be or have been before the participle.","pattern":"The bridge is thought **to have been built** in 1900.","commonMistakes":["To have built is active; to have been built is passive. The participant’s role determines which is needed."],"examples":["The event was yesterday: “She is believed **to have prepared** the visitor guide then.”","The event was yesterday: “She is believed **to have restored** the old portrait then.”"],"skill":"meaning"},{"title":"Arrange for someone else to do something","explanation":"**Have / get + object + past participle** often describes a service or arranged action. The subject arranges or experiences the action rather than necessarily performing it. Get is often less formal. The causative verb carries tense.","pattern":"We **had the roof repaired**.","commonMistakes":["We had repaired the roof is past perfect active and normally says we did the repair; it is a different structure."],"examples":["Someone else did the task for us. Complete the causative: “We had the visitor guide **prepared**.”","Someone else did the task for us. Complete the causative: “We had the old portrait **restored**.”"],"skill":"contrast"},{"title":"Get-passives and affected experiences","explanation":"Get + participle can form an informal passive, especially for events or changes affecting someone. Causative have can also describe an unwelcome experience that was not arranged, such as having a bag stolen. Meaning and context matter.","pattern":"The parcel **got damaged**. / She **had her bag stolen**.","commonMistakes":["Have something done does not always imply the subject chose or paid for the action."],"examples":["Use a perfect passive infinitive: “The visitor guide is thought to have **been prepared** already.”","Use a perfect passive infinitive: “The old portrait is thought to have **been restored** already.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Report beliefs impersonally, combine passive with perfect forms, and describe services someone arranges.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Impersonal reporting","explanation":"A reporting passive can avoid naming who holds a view: **It is believed that ...**. Another pattern makes the reported subject the main subject: **She is believed to ...**. These constructions report a claim; they do not establish that it is true.","pattern":"It is believed that she lives here. / She is believed **to live** here.","commonMistakes":["Do not confuse the time of the belief with the time of the event being reported."],"examples":["Report a habitual activity impersonally: “She is believed **to prepare** the visitor guide every week.”","Report a habitual activity impersonally: “She is believed **to restore** the old portrait every week.”"],"skill":"form","id":"advanced-passives-foundation-1","domain":"information","referenceIds":["bc-advanced-passives"],"readingVersion":"core-2026-09-v3"},{"title":"Earlier events after a reporting passive","explanation":"Use a **perfect infinitive** when the reported event is earlier than the reporting reference: is believed to have left. A continuous infinitive can show an ongoing activity: is thought to be working. A passive infinitive adds be or have been before the participle.","pattern":"The bridge is thought **to have been built** in 1900.","commonMistakes":["To have built is active; to have been built is passive. The participant’s role determines which is needed."],"examples":["The event was yesterday: “She is believed **to have prepared** the visitor guide then.”","The event was yesterday: “She is believed **to have restored** the old portrait then.”"],"skill":"meaning","id":"advanced-passives-foundation-2","domain":"information","referenceIds":["bc-advanced-passives"],"readingVersion":"core-2026-09-v3"},{"title":"Arrange for someone else to do something","explanation":"**Have / get + object + past participle** often describes a service or arranged action. The subject arranges or experiences the action rather than necessarily performing it. Get is often less formal. The causative verb carries tense.","pattern":"We **had the roof repaired**.","commonMistakes":["We had repaired the roof is past perfect active and normally says we did the repair; it is a different structure."],"examples":["Someone else did the task for us. Complete the causative: “We had the visitor guide **prepared**.”","Someone else did the task for us. Complete the causative: “We had the old portrait **restored**.”"],"skill":"contrast","id":"advanced-passives-foundation-3","domain":"information","referenceIds":["bc-advanced-passives"],"readingVersion":"core-2026-09-v3"},{"title":"Get-passives and affected experiences","explanation":"Get + participle can form an informal passive, especially for events or changes affecting someone. Causative have can also describe an unwelcome experience that was not arranged, such as having a bag stolen. Meaning and context matter.","pattern":"The parcel **got damaged**. / She **had her bag stolen**.","commonMistakes":["Have something done does not always imply the subject chose or paid for the action."],"examples":["Use a perfect passive infinitive: “The visitor guide is thought to have **been prepared** already.”","Use a perfect passive infinitive: “The old portrait is thought to have **been restored** already.”"],"skill":"application","id":"advanced-passives-foundation-4","domain":"information","referenceIds":["bc-advanced-passives"],"readingVersion":"core-2026-09-v3"},{"domain":"information","id":"get-passive-prepositional-passive","title":"Get-passives and prepositional passives","explanation":"Get + past participle can present an event affecting a subject, often in less formal language. Some prepositional verbs allow the complement of the preposition to become the passive subject, leaving the preposition at the end. The naturalness of such passives depends on the verb combination and what the discourse is about.","pattern":"She **got promoted**. / The issue **was dealt with**.","examples":["The children **were looked after**.","He **got caught** in the rain."],"commonMistakes":["Get + adjective can describe becoming a state rather than a passive event: get hungry. Not every preposition phrase can naturally supply a passive subject."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"information","id":"passive-chains-and-causatives","title":"Passive infinitives, perfect forms and causative meanings","explanation":"Passive be can combine with modals, perfect and infinitive constructions. Read the chain one step at a time to identify time and voice. Have/get + object + participle commonly describes arranging a service, but have can also introduce an unwanted experience. Active causative patterns use a different arrangement.","pattern":"might **have been repaired** · needs **to be checked**","examples":["We **had the roof repaired**.","She **had her bag stolen**."],"commonMistakes":["Had her bag stolen does not normally mean she arranged the theft. Context distinguishes a service causative from an affected-person experience."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["It is believed that she lives here. / She is believed **to live** here.","The bridge is thought **to have been built** in 1900.","We **had the roof repaired**.","The parcel **got damaged**. / She **had her bag stolen**."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["agreement-advanced"],"readingReferenceIds":["bc-advanced-passives","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='advanced-passives'
